  // ---- v118 新增：成语与俗语（30题，依据四年级课本与日积月累） ----
  function cn4_idioms_pool() {
    const idioms = [
      ['人不可貌相，海水不可斗量', '不能只凭外表评价人', ['海很深无法测量', '海水很多', '人长得高大']],
      ['一言既出，驷马难追', '话说出口就难以收回', ['一句话值四匹马', '马跑得很快', '说话要声音大']],
      ['尺有所短，寸有所长', '人和事物各有长处短处', ['尺比寸长', '尺和寸都短', '寸比尺长']],
      ['差之毫厘，谬以千里', '开始差一点点，结果会错得很远', ['误差很小没关系', '毫厘等于千里', '做事要粗心']],
      ['机不可失，时不再来', '机会难得，不能错过', ['机器不能丢失', '时间不会重来', '机会来了要拒绝']],
      ['病从口入，祸从口出', '饮食不卫生会生病，说话不注意会惹祸', ['病是从嘴巴里进去的', '祸是从嘴巴出来的', '少说话就不生病']],
      ['比上不足，比下有余', '跟好的比差些，跟差的比好些', ['比上面差比下面好', '上面不够下面多', '上下都不如']],
      ['有志者事竟成', '有志向的人最终能成功', ['有志气的人一定赢', '有志气的人做事一定能成', '做事情要有竞争']],
      ['志当存高远', '人应当有远大的志向', ['志向应该很高', '人站得高看得远', '志愿存起来']],
      ['重整旗鼓', '失败后重新振作起来', ['重新整理旗帜', '把鼓修好', '整顿队伍出发打仗']],
      ['得心应手', '做事熟练，运用自如', ['心里想到手上做到', '心满意足', '手很灵活']],
      ['手舞足蹈', '高兴得手和脚都舞动起来', ['一边跳舞一边走路', '手和脚都在动', '手脚发抖']],
      ['出乎意料', '超出了预先的估计', ['早就猜到了', '在心里意料', '结果让人想不到']],
      ['如虎添翼', '本领强的人又得到帮助，更强了', ['老虎长翅膀', '像老虎一样凶猛', '帮助老虎']],
      ['画蛇添足', '做了多余的事，反而不恰当', ['画蛇加上脚', '画蛇画得好', '添上脚更好看']],
      ['滥竽充数', '没有真本领的人混在行家里面充数', ['乐器很乱', '吹竽的人很多', '会吹竽的人']],
      ['自相矛盾', '说话做事前后不一致', ['自己和自己打仗', '矛和盾很锋利', '互相矛盾的人']],
      ['守株待兔', '不努力而妄想得到意外收获', ['守着树等兔子', '爱护树木和兔子', '养兔子']],
      ['掩耳盗铃', '自己欺骗自己', ['捂住耳朵偷铃铛', '耳朵不好听不见', '把铃铛藏起来']],
      ['亡羊补牢', '出了问题及时补救还不算晚', ['羊丢了很伤心', '修补羊圈', '把羊圈修牢固']],
      ['井底之蛙', '见识狭窄的人', ['井底的青蛙', '井很深', '青蛙很小']],
      ['精卫填海', '比喻意志坚定，不畏艰难', ['精卫鸟去填海', '把海填平', '填海的鸟']],
      ['开天辟地', '形容开创前所未有的事业', ['把天地打开', '天空裂开', '天地很大']],
      ['惊天动地', '形容声势浩大或影响巨大', ['天空大地都动了', '雷声很大', '地震了']],
      ['风平浪静', '没有风浪，比喻平静无事', ['风很大浪很高', '海上没有风浪', '风吹得很平']],
    ];
    const items = idioms.map(function (x) {
      return mkChoice('"' + x[0] + '"的意思是？', x[1], x[2]);
    });
    items.push(
      mkJudge('"有志者事竟成"告诉我们：人只要有志向，并努力去做，事情就能成功。', true),
      mkJudge('"尺有所短，寸有所长"是说尺和寸都有缺点。', false),
      mkChoice('下面成语中，表达"失败后重新振作"意思的是？', '重整旗鼓', ['手舞足蹈', '井底之蛙', '画蛇添足']),
      mkChoice('"一言既出，驷马难追"告诉我们做人要？', '说话算话', ['说话大声', '少说话', '说话要快']),
      mkChoice('下面哪个词语形容"见识短浅"？', '井底之蛙', ['开天辟地', '风平浪静', '得心应手']),
      mkChoice('《陀螺》一课中"人不可貌相，海水不可斗量"的意思是？', '不能只凭外表看人，小陀螺也能打败大陀螺', ['海水很多无法量', '人长得高大才好', '不要以貌取人就能赢']
    ));
    return items;
  }

