  // ---- v118 新增：古诗文鉴赏（30题，依据四年级上下册古诗与日积月累） ----
  function cn4_poetry_pool() {
    const poems = [
      ['《暮江吟》', '白居易', '唐代', '一道残阳铺水中，半江瑟瑟半江红', '傍晚江边美景'],
      ['《题西林壁》', '苏轼', '宋代', '不识庐山真面目，只缘身在此山中', '当局者迷'],
      ['《雪梅》', '卢钺', '宋代', '梅须逊雪三分白，雪却输梅一段香', '梅雪各有所长'],
      ['《出塞》', '王昌龄', '唐代', '但使龙城飞将在，不教胡马度阴山', '盼望良将守卫边疆'],
      ['《凉州词》', '王翰', '唐代', '醉卧沙场君莫笑，古来征战几人回', '将士的豪迈'],
      ['《夏日绝句》', '李清照', '宋代', '生当作人杰，死亦为鬼雄', '赞颂英雄气概'],
      ['《鹿柴》', '王维', '唐代', '空山不见人，但闻人语响', '山林的幽静'],
      ['《四时田园杂兴》', '范成大', '宋代', '童孙未解供耕织，也傍桑阴学种瓜', '乡村劳动童趣'],
      ['《宿新市徐公店》', '杨万里', '宋代', '儿童急走追黄蝶，飞入菜花无处寻', '儿童追蝶的童趣'],
      ['《清平乐·村居》', '辛弃疾', '宋代', '最喜小儿亡赖，溪头卧剥莲蓬', '农家生活闲适'],
      ['《芙蓉楼送辛渐》', '王昌龄', '唐代', '洛阳亲友如相问，一片冰心在玉壶', '清白高洁的品格'],
      ['《塞下曲》', '卢纶', '唐代', '欲将轻骑逐，大雪满弓刀', '将军雪夜追敌'],
      ['《墨梅》', '王冕', '元代', '不要人夸好颜色，只留清气满乾坤', '淡泊名利的品格'],
    ];
    const items = [];
    poems.forEach(function (p) {
      items.push(mkChoice(p[0] + '的作者是？', p[1], ['李白', '杜甫', '王维', '白居易'].filter(function (x) { return x !== p[1]; }).slice(0, 3)));
      items.push(mkChoice(p[0] + '中"' + p[3] + '"表达的思想感情是？', p[4], ['思乡之情', '赞美春天', '旅途劳顿', '感叹时光'].filter(function (x) { return x !== p[4]; }).slice(0, 3)));
    });
    items.push(
      mkFill('"不识庐山真面目"的下一句是"____"。', '只缘身在此山中'),
      mkFill('"空山不见人"的下一句是"____"。', '但闻人语响'),
      mkFill('"生当作人杰"的下一句是"____"。', '死亦为鬼雄'),
      mkFill('"一片冰心在玉壶"的上一句是"____"。', '洛阳亲友如相问'),
      mkJudge('《题西林壁》告诉我们"当局者迷，旁观者清"的道理。', true),
      mkJudge('《雪梅》一诗说明梅和雪各有长处，也各有短处。', true),
      mkChoice('"不识庐山真面目"中"缘"的意思是？', '因为', ['缘分', '边缘', '缘故']),
      mkChoice('"儿童急走追黄蝶"中"走"的意思是？', '跑', ['走路', '离开', '行走']),
      mkChoice('"梅须逊雪三分白"中"逊"的意思是？', '比不上', ['谦逊', '退让', '超过']),
      mkChoice('《夏日绝句》赞颂的历史人物是？', '项羽', ['刘邦', '岳飞', '文天祥']),
      mkChoice('"醉卧沙场君莫笑"中"沙场"指的是？', '战场', ['沙滩', '操场', '广场']),
      mkFill('《出塞》中"但使龙城飞将在"的下一句是"____"。', '不教胡马度阴山'),
      mkJudge('《清平乐·村居》是一首词，"清平乐"是词牌名。', true),
      mkChoice('《四时田园杂兴》写的是哪个季节的田园生活？', '夏天', ['春天', '秋天', '冬天']),
      mkFill('《宿新市徐公店》中"飞入菜花无处寻"的上一句是"____"。', '儿童急走追黄蝶'),
      mkChoice('"最喜小儿亡赖"中"亡赖"的意思是？', '顽皮、淘气', ['不讲理', '无赖', '很懒']),
      mkJudge('《暮江吟》描写的是傍晚江边的美丽景色。', true),
      mkChoice('"半江瑟瑟半江红"中"瑟瑟"形容？', '碧绿的颜色', ['发抖', '寒冷', '沙沙声']),
      mkFill('《墨梅》中"只留清气满乾坤"的上一句是"____"。', '不要人夸好颜色'),
      mkJudge('《芙蓉楼送辛渐》是一首送别诗，表达了诗人清白高洁的品格。', true),
      mkChoice('《塞下曲》描写的是？', '将军雪夜追击敌人的情景', ['春天郊游', '田园劳动', '月夜散步']),
      mkFill('《鹿柴》中"但闻人语响"的上一句是"____"。', '空山不见人'),
      mkChoice('《凉州词》"醉卧沙场君莫笑"表现的是？', '将士视死如归的豪迈', ['将士贪杯', '将士发愁', '将士害怕'],
    ));
    return items;
  }

  // ---- 阅读理解（记叙文） ----
  function cn4_reading_pool() {
    const passages = [
      {
        text: '春天来了，万物复苏。小草从地里探出头来，树枝上长出了嫩绿的新叶。花园里，桃花、杏花、梨花竞相开放，红的像火，粉的像霞，白的像雪。小鸟在枝头唱歌，蝴蝶在花丛中飞舞。小朋友们脱去厚厚的冬装，在草地上快乐地奔跑。',
        qs: [
          mkChoice('这段话主要描写的是哪个季节？', '春天', ['夏天', '秋天', '冬天']),
          mkChoice('"小草从地里探出头来"用了什么修辞手法？', '拟人', ['比喻', '夸张', '排比']),
          mkChoice('文中"红的像火，粉的像霞，白的像雪"描写的是？', '花', ['树叶', '云彩', '蝴蝶']),
          mkJudge('这段话写了春天的景色，表达了作者对春天的喜爱。', true),
          mkChoice('"竞相开放"的意思是？', '花争先恐后地开放', ['花慢慢地枯萎', '花被风吹落', '花按顺序开放']),
          mkFill('文中的拟人句"小草从地里____"，生动地写出了小草的生命力。', '探出头来'),
        ],
      },
      {
        text: '放学后，小明看见一位老奶奶在马路边摔倒了。他连忙跑过去，把老奶奶扶起来，关心地问："奶奶，您没事吧？"老奶奶笑着说："没事，谢谢你，好孩子。"小明一直把老奶奶送到了家门口，才高高兴兴地回家去。',
        qs: [
          mkChoice('这段话主要写了一件什么事？', '小明扶起摔倒的老奶奶并送她回家', ['小明放学回家', '老奶奶散步', '小明去老奶奶家玩']),
          mkChoice('从这段话可以看出小明是个怎样的孩子？', '乐于助人', ['贪玩', '胆小', '粗心']),
          mkJudge('小明把老奶奶送回家后才自己回家的。', true),
          mkFill('小明看到老奶奶摔倒后，____（填动词）过去扶起来。', '连忙跑'),
          mkChoice('"连忙跑过去"中的"连忙"表现了小明怎样的心情？', '急切地想帮助老奶奶', ['很害怕', '不想去', '被迫去']),
          mkChoice('用"谁+做了什么事"概括这段话，正确的是？', '小明扶老奶奶回家', ['老奶奶摔倒了', '小明放学了', '小明高高兴兴回家']),
        ],
      },
      {
        text: '放学时，天空突然下起了大雨。同学们都被家长接走了，只有小明站在校门口发呆。这时，一个熟悉的身影出现在雨幕中——是妈妈！她打着伞，深一脚浅一脚地跑过来，裤脚全湿透了。回家的路上，妈妈把伞一个劲地往小明这边移，自己的半个肩膀却被雨水打湿了。小明发现后，悄悄地把伞推向妈妈那边。',
        qs: [
          mkChoice('这段话主要写了一件什么事？', '下雨天妈妈给小明送伞，小明把伞推回妈妈那边', ['小明放学回家', '妈妈去学校开家长会', '小明在雨中玩耍']),
          mkChoice('"深一脚浅一脚"说明了什么？', '雨大路滑，妈妈走得很吃力', ['妈妈跑得很快', '妈妈心情很好', '路面很平整']),
          mkChoice('对"妈妈把伞一个劲地往小明这边移"理解正确的是？', '妈妈宁可自己淋雨也想护住孩子', ['妈妈不小心拿歪了伞', '妈妈不想打伞', '伞太重了拿不动']),
          mkJudge('小明悄悄把伞推向妈妈那边，说明他懂得关心妈妈。', true),
          mkChoice('文中最能体现母爱的细节是？', '妈妈半个肩膀被雨水打湿', ['天空下起了大雨', '同学们被接走了', '小明站在校门口']),
          mkFill('用"谁+在什么情况下+做了什么"概括本文：下雨时，____给小明送伞。', '妈妈'),
        ],
      },
      {
        text: '校园的早晨是安静的。操场上空荡荡的，教室里传来朗朗的读书声。校园的早晨又是热闹的。同学们有的扫地，有的浇花，有的在走廊里背诵古诗。太阳升起来了，金色的阳光洒在教学楼上，洒在花坛里，也洒在同学们的笑脸上。新的一天开始了。',
        qs: [
          mkChoice('这段话围绕什么来写校园的早晨？', '校园早晨安静和热闹的特点', ['校园的操场很大', '同学们爱扫地', '太阳升起的时间']),
          mkChoice('"朗朗的读书声"中"朗朗"形容？', '读书声音清楚响亮', ['读书很慢', '声音很小', '读书的人多']),
          mkChoice('文中"有的……有的……有的……"写出了什么？', '同学们的活动丰富多彩', ['同学们很吵闹', '老师要求严格', '校园很大']),
          mkJudge('"金色的阳光洒在教学楼上，洒在花坛里，也洒在同学们的笑脸上"运用了排比。', true),
          mkChoice('这段话的写作顺序是？', '先写安静，再写热闹', ['先写热闹，再写安静', '只写安静', '只写热闹']),
          mkJudge('这段话属于写景的文章。', true),
        ],
      },
      {
        text: '小华在教室里踢毽子，不小心把黑板上的玻璃打碎了。教室里没有别人，他想：反正没人看见，赶快走吧。可是走了几步，他又想起老师说过的话："做人要诚实。"于是，他回到教室，主动向老师承认了错误。老师不但没有批评他，还表扬他是一个诚实勇敢的好孩子。',
        qs: [
          mkChoice('这段话主要写了一件什么事？', '小华打碎玻璃后主动承认错误', ['小华在教室踢毽子', '老师表扬了全班同学', '玻璃被风吹碎了']),
          mkChoice('"他想：反正没人看见，赶快走吧"属于什么描写？', '心理描写', ['外貌描写', '环境描写', '语言描写']),
          mkChoice('小华是个怎样的孩子？', '知错就改、诚实', ['胆小怕事', '爱撒谎', '不爱运动']),
          mkJudge('老师批评了小华打碎玻璃的事。', false),
          mkChoice('"做人要诚实"这句话是谁说的？', '老师', ['小华', '同学', '家长']),
          mkChoice('这个故事告诉我们什么道理？', '犯了错误要勇于承认', ['没人看见就可以走', '踢毽子不好玩', '玻璃很容易碎']),
        ],
      },
    ];
    const items = [];
    passages.forEach(function (p) {
      p.qs.forEach(function (q) { items.push(Object.assign({}, q, { passage: p.text })); });
    });
    return items;
  }

