  // ---- 汉字（字形结构、部首、查字典） ----
  function cn5_chars_pool() {
    const struct = [
      ['"休"字的结构是？', '左右结构', ['上下结构', '半包围结构', '独体字']],
      ['"音"字的结构是？', '上下结构', ['左右结构', '半包围结构', '全包围结构']],
      ['"问"字的结构是？', '半包围结构', ['左右结构', '上下结构', '全包围结构']],
      ['"回"字的结构是？', '全包围结构', ['左右结构', '上下结构', '半包围结构']],
      ['"本"字的结构是？', '独体字', ['左右结构', '上下结构', '半包围结构']],
      ['"森"字的结构是？', '品字结构', ['左右结构', '上下结构', '全包围结构']],
      ['"翅"字的结构是？', '半包围结构', ['左右结构', '上下结构', '独体字']],
      ['"裹"字的结构是？', '上中下结构', ['左右结构', '全包围结构', '独体字']],
    ];
    const radicals = [
      ['"问"字用部首查字法，应查哪个部首？', '门', ['口', '日', '问字框内']],
      ['"尘"字的部首是？', '小', ['土', '一', '川']],
      ['下列哪个字的部首是"氵"？', '海', ['悔', '梅', '每']],
      ['下列哪个字的部首是"艹"？', '草', ['早', '章', '卓']],
      ['"想"字的部首是？', '心', ['相', '目', '木']],
      ['"闻"字用部首查字法应查？', '门', ['耳', '日', '口']],
      ['"露"字的部首是？', '雨', ['路', '各', '口']],
      ['"病"字的部首是？', '疒', ['丙', '一', '广']],
    ];
    const items = [];
    struct.forEach(function (s) { items.push(mkChoice(s[0], s[1], s[2])); });
    radicals.forEach(function (s) { items.push(mkChoice(s[0], s[1], s[2])); });
    items.push(
      mkFill('"鼎"字共有____画。', '12'),
      mkFill('用数笔画查字法，"凸"字有____画。', '5'),
      mkFill('"凹"字有____画。', '5'),
      mkChoice('用音序查字法查"慈"字，应先查字母？', 'C', ['D', 'Z', 'S']),
      mkChoice('用音序查字法查"韵"字，应先查字母？', 'Y', ['J', 'U', 'W']),
      mkChoice('用音序查字法查"恩"字，应先查字母？', 'E', ['N', 'A', 'F']),
      mkChoice('不知道读音也不知部首的生字，最好用？', '数笔画查字法', ['音序查字法', '部首查字法', '上网搜索']),
      mkChoice('知道读音不会写的字，最好用？', '音序查字法', ['部首查字法', '数笔画查字法', '猜字法']),
      mkJudge('"森"字是由三个"木"组成的品字结构。', true),
      mkJudge('"明"是左右结构，左边是"日"，右边是"月"。', true),
      mkJudge('"问"字外面是"门"，里面的"口"也叫声旁。', false),
      mkChoice('"休"字用"人"靠"木"表示休息，这种造字方法是？', '会意', ['象形', '形声', '指事']),
      mkChoice('下列哪组都是形声字？', '清、晴、请', ['森、炎、从', '休、看、从', '上、下、本']),
      mkFill('"鼎"字用部首查字法，应查____部。', '目')
    );
    return items;
  }

