  // ---- 阅读理解（说明文） ----
  function cn5_reading_pool() {
    const passages = [
      {
        text: '鲸是海洋中的庞然大物。它虽然生活在水中，却不是鱼类，而是哺乳动物。鲸用肺呼吸，需要浮出水面换气。鲸分为两大类：一类是须鲸，没有牙齿，以小鱼小虾为食；另一类是齿鲸，有锋利的牙齿，以海豹、海鱼为食。最大的蓝鲸体长可达30米，体重可达150吨，是地球上现存最大的动物。',
        qs: [
          mkChoice('这段话主要介绍了鲸的什么？', '鲸的特点和分类', ['鲸的习性', '鲸的进化', '鲸的捕食']),
          mkChoice('鲸不属于鱼类的原因是？', '鲸是哺乳动物，用肺呼吸', ['鲸体型太大', '鲸没有鳞片', '鲸生活在海洋里']),
          mkChoice('鲸分为哪两大类？', '须鲸和齿鲸', ['蓝鲸和虎鲸', '大鲸和小鲸', '白鲸和抹香鲸']),
          mkJudge('蓝鲸是地球上现存最大的动物。', true),
          mkChoice('"体长可达30米，体重可达150吨"用了什么说明方法？', '列数字', ['打比方', '作比较', '下定义']),
          mkChoice('这段话的说明顺序是？', '先总述特点，再分类介绍', ['按时间顺序', '按地点顺序', '按大小顺序']),
          mkFill('本文的说明对象是____。', '鲸'),
          mkChoice('根据这段话，须鲸的食物是？', '小鱼小虾', ['海豹', '大鱼', '芦苇']),
        ],
      },
      {
        text: '仙人掌是一种耐旱植物，主要生长在沙漠地区。它的叶子退化成了刺，这样可以减少水分蒸发。仙人掌的茎肥厚多汁，能够储存大量水分。它的根系非常发达，能深入地下吸收水分。即使在长期干旱的条件下，仙人掌也能顽强地生存。仙人掌不仅能观赏，有些品种的果实还可以食用。',
        qs: [
          mkChoice('这段话主要介绍了仙人掌的什么？', '仙人掌的特点和用途', ['仙人掌的花', '仙人掌的种植', '仙人掌的价格']),
          mkChoice('仙人掌的叶子退化成刺的原因是？', '减少水分蒸发', ['美观', '防御敌人', '吸引昆虫']),
          mkChoice('仙人掌能在沙漠生存的关键是什么？', '茎能储水，根系发达', ['长得快', '有刺', '叶子少']),
          mkJudge('仙人掌只能观赏，不能食用。', false),
          mkChoice('"叶子退化成了刺"中"退化"的意思是？', '生物体某部分在进化中变小或消失', ['变得更好', '突然消失', '被风吹掉']),
          mkChoice('这段话说明仙人掌的特点用了什么结构？', '总—分', ['分—总', '总—分—总', '并列']),
          mkJudge('这段话属于事物说明文。', true),
          mkChoice('仙人掌体内能储存大量水分的部位是？', '茎', ['刺', '花', '果实']),
        ],
      },
      {
        text: '蜜蜂是勤劳的昆虫。一只蜜蜂酿造一千克蜜，要飞行大约45万千米，相当于绕地球飞行11圈。蜜蜂不仅勤劳，还是"天才的建筑师"。它们建造的蜂巢由无数个正六边形组成，这种结构用料最少、容量最大，十分精巧。科学家受到蜂巢的启发，把这种结构应用到了航天和建筑领域。',
        qs: [
          mkChoice('这段话说明了蜜蜂的什么特点？', '勤劳，还是"天才的建筑师"', ['懒惰', '凶猛', '飞行速度快']),
          mkChoice('"要飞行大约45万千米，相当于绕地球飞行11圈"用了什么说明方法？', '列数字、作比较', ['打比方、拟人', '下定义、分类', '画图表、举例']),
          mkChoice('蜂巢的结构是？', '由无数个正六边形组成，用料少容量大', ['圆形的，很柔软', '方形的，很坚硬', '三角形的，很密集']),
          mkJudge('科学家把蜂巢结构应用到了航天和建筑领域。', true),
          mkChoice('称蜜蜂为"天才的建筑师"，引号的作用是？', '特殊含义，肯定蜜蜂的精巧', ['直接引用原话', '表示讽刺否定', '表示声音延长']),
          mkFill('本文说明蜜蜂的两个特点：勤劳和会建造____。', '蜂巢'),
          mkChoice('"勤劳"一词在文中的表达作用是？', '突出蜜蜂不辞辛劳的品质', ['说明蜜蜂数量多', '说明蜜蜂飞得快', '说明蜜蜂寿命长']),
        ],
      },
      {
        text: '大熊猫是我国的国宝，主要分布在四川、陕西、甘肃的山区。它憨态可掬，圆滚滚的身体，黑白相间的毛色，标志性的黑眼圈让人一见就喜欢。大熊猫看起来笨拙，爬起树来却十分灵活。它99%的食物是竹子，每天要花十多个小时进食。大熊猫数量稀少，被誉为"活化石"，是我国一级保护动物。',
        qs: [
          mkChoice('这段话主要介绍了大熊猫的什么？', '大熊猫的外形、习性和珍稀', ['大熊猫的价格', '大熊猫的进化史', '大熊猫的叫声']),
          mkChoice('大熊猫主要分布在哪里？', '四川、陕西、甘肃的山区', ['北京、上海的公园', '东北的森林', '南方的海岛']),
          mkChoice('大熊猫的食物主要是？', '竹子', ['肉类', '水果', '昆虫']),
          mkJudge('大熊猫是我国的二级保护动物。', false),
          mkChoice('"憨态可掬"的意思是？', '天真而显单纯的样子，十分可爱', ['非常凶猛的样子', '笨重讨厌的样子', '无精打采的样子']),
          mkChoice('大熊猫被誉为"活化石"是因为？', '数量稀少且历史悠久', ['长得像化石', '不会动', '毛色像石头']),
          mkFill('大熊猫每天要花十多个小时____。', '进食'),
        ],
      },
    ];
    const items = [];
    passages.forEach(function (p) {
      p.qs.forEach(function (q) { items.push(Object.assign({}, q, { passage: p.text })); });
    });
    return items;
  }

