  // 六年级 · 题库
  // ============================================================

  // ---- 词语（成语运用、俗语谚语） ----
  function cn6_words_pool() {
    return [
      mkChoice('下列成语使用正确的是？', '他学习刻苦，终于水到渠成地考上了理想的中学。', ['他学习刻苦，终于画蛇添足地考上了中学。', '他学习刻苦，终于亡羊补牢地考上了中学。', '他学习刻苦，终于守株待兔地考上了中学。']),
      mkChoice('"三人行，必有我师"告诉我们？', '要虚心向别人学习', ['要和朋友一起走', '要当老师', '三个人一起走']),
      mkChoice('下列哪个是关于团结的谚语？', '众人拾柴火焰高', ['一箭双雕', '画蛇添足', '亡羊补牢']),
      mkChoice('"千里送鹅毛"的下一句是？', '礼轻情意重', ['物轻情意重', '人远情意近', '路远心意坚']),
      mkJudge('"塞翁失马"比喻坏事不一定就是坏事，可能变成好事。', true),
      mkChoice('下列成语意思相近的是？', '画蛇添足 和 多此一举', ['画蛇添足 和 锦上添花', '亡羊补牢 和 未雨绸缪', '守株待兔 和 奋发图强']),
      mkFill('"巧舌如____"（填成语缺字）', '簧', ['簧', '黄', '惶', '皇']),
      mkChoice('下列哪个成语用来形容人多？', '人山人海', ['门可罗雀', '寥寥无几', '人迹罕至']),
      mkJudge('"世上无难事，只怕有心人"是说只要有决心，没有办不成的事。', true),
      mkChoice('"一日千里"形容的是？', '进步或发展非常快', ['走得远', '时间短', '距离长']),
      mkChoice('下列成语使用不恰当的是？', '教室里同学们争论得鸦雀无声。', ['教室里安静得鸦雀无声。', '同学们讨论得热火朝天。', '联欢会上大家载歌载舞。']),
      mkChoice('"亡羊补牢"告诉我们什么道理？', '发现问题及时补救还不算晚', ['羊圈修得越牢越好', '丢了羊就要放弃', '养羊不需要羊圈']),
      mkChoice('与"尺有所短，寸有所长"意思相近的是？', '人各有所长，也各有所短', ['尺比寸长', '寸比尺短', '测量要用尺子']),
      mkChoice('"磨刀不误砍柴工"告诉我们？', '做好准备能提高效率', ['砍柴不需要刀', '磨刀太浪费时间', '要先磨刀再砍柴，两件事无关']),
      mkChoice('下列哪组都是描写人物神态的成语？', '眉开眼笑、目瞪口呆、愁眉苦脸', ['健步如飞、手疾眼快', '拔地而起、一碧千里', '五光十色、五彩缤纷']),
      mkChoice('下列哪组都是描写自然景物的成语？', '崇山峻岭、波光粼粼、鸟语花香', ['提心吊胆、胆战心惊', '口若悬河、妙语连珠', '东张西望、左顾右盼']),
      mkChoice('"百发百中"中的"发"意思是？', '射出（箭）', ['头发', '出发', '发展']),
      mkFill('"不入虎穴，焉得____"（填空）', '虎子'),
      mkFill('"路遥知马力，日久见____"（填空）', '人心'),
      mkJudge('"千里送鹅毛，礼轻情意重"说明礼物虽轻但情谊深厚。', true),
      mkJudge('"三个臭皮匠，顶个诸葛亮"说明集体智慧的力量。', true),
      mkChoice('"水滴石穿"告诉我们的道理是？', '坚持不懈就能成功', ['石头很硬', '水滴很小', '滴水的声音好听']),
      mkChoice('形容读书多、学识渊博的成语是？', '学富五车', ['一窍不通', '不学无术', '孤陋寡闻']),
      mkChoice('与"雪中送炭"意思相反的是？', '雪上加霜', ['助人为乐', '扶危济困', '慷慨解囊']),
      mkChoice('下列俗语与"台上一分钟，台下十年功"意思相近的是？', '梅花香自苦寒来', ['看花容易绣花难', '远水解不了近渴', '众人拾柴火焰高']),
      mkChoice('"韦编三绝"形容？', '读书勤奋刻苦', ['睡觉很香', '跑步很快', '吃饭很多']),
      mkChoice('"画龙点睛"比喻？', '在关键处加上精辟语句使内容更生动', ['画龙很难', '眼睛很重要', '点睛就会飞走']),
      mkChoice('下列成语出自寓言故事的是？', '自相矛盾', ['山清水秀', '万紫千红', '兴高采烈']),
      mkChoice('"专心致志"的近义词是？', '全神贯注', ['三心二意', '心不在焉', '东张西望']),
      mkChoice('与"井然有序"意思相反的是？', '杂乱无章', ['井井有条', '有条不紊', '秩序井然']),
      // v112 M6+L1：补判断题（错误项 + 解析，平衡正确率）
      mkJudge('"画蛇添足"和"多此一举"意思相反。', false, '画蛇添足与多此一举都指做了多余、不必要的事，意思相近，不是相反。'),
      mkJudge('"自相矛盾"出自中国古代神话传说。', false, '自相矛盾出自战国时期韩非子的寓言故事，讲卖矛和盾的人说法前后抵触，不是神话传说。')
    ];
  }

  // ---- 句子（复句、修改病句） ----
  function cn6_sentences_pool() {
    return [
      mkChoice('下列哪个是因果复句？', '因为下雨，所以比赛取消了。', ['虽然下雨，但比赛继续。', '不但下雨，而且刮风。', '如果下雨，比赛就取消。']),
      mkChoice('修改病句："通过这次活动，使我受到了教育。"正确改法是？', '这次活动使我受到了教育。', ['通过这次活动使我受到教育了。', '通过活动，使我受了教育。', '通过这次活动使教育受到了我。']),
      mkChoice('"不但…而且…"表示什么关系？', '递进', ['因果', '转折', '条件']),
      mkChoice('修改病句："我估计他这道题一定做对了。"错误类型是？', '前后矛盾', ['用词不当', '成分残缺', '语序不当']),
      mkFill('"虽然天气很冷，____同学们都按时到校。"（填关联词）', '但是', ['但是', '而且', '所以', '虽然']),
      mkJudge('"只有好好学习，才能取得好成绩"是条件复句。', true),
      mkChoice('下列句子无语病的是？', '我们必须养成勤俭节约的好习惯。', ['我们必须养成勤俭节约。', '我们必须养成勤俭节约的好作风。', '我们必须把勤俭节约养成习惯。']),
      mkChoice('"既然…就…"表示什么关系？', '因果', ['递进', '转折', '假设']),
      mkJudge('"不但他学习好，而且品德好"和"他不但学习好，而且品德好"语序都可以。', false),
      mkChoice('修改病句："他的写作水平明显改善了。"应改为？', '他的写作水平明显提高了。', ['他的写作水平明显增加了。', '他的写作水平明显进步了。', '他的写作水平明显发展了。']),
      mkChoice('"虽然…但是…"表示什么关系？', '转折', ['递进', '因果', '并列']),
      mkChoice('"如果…就…"表示什么关系？', '假设', ['转折', '递进', '因果']),
      mkChoice('修改病句："我们要养成讲卫生。"错误类型是？', '成分残缺', ['前后矛盾', '重复啰嗦', '语序不当']),
      mkChoice('修改病句："他经常回忆过去的往事。"错误类型是？', '重复啰嗦', ['前后矛盾', '成分残缺', '用词不当']),
      mkChoice('修改病句："全校师生和班主任都参加了植树活动。"错误类型是？', '概念并列不当', ['前后矛盾', '重复啰嗦', '语序不当']),
      mkChoice('"即使…也…"表示什么关系？', '假设', ['转折', '递进', '因果']),
      mkChoice('"不但…还…"表示？', '递进', ['并列', '转折', '条件']),
      mkChoice('修改病句："他基本上把坏习惯改掉了。"正确改法是？', '他把坏习惯基本改掉了。', ['他基本上把坏习惯全改掉了。', '他把坏习惯基本上全改掉了。', '基本上他坏习惯改掉了。']),
      mkChoice('修改病句："博物馆展出了两千多年前新出土的文物。"应改为？', '博物馆展出了新出土的两千多年前的文物。', ['博物馆新出土了两千多年前的文物。', '两千多年前博物馆展出了文物。', '展出了博物馆新出土的文物。']),
      mkFill('"与其在家等着，____出门走走。"（填关联词）', '不如', ['不如', '就', '都', '才']),
      mkFill('"宁可自己吃亏，____占别人便宜。"（填关联词）', '不', ['不', '还', '也', '再']),
      mkJudge('"一边…一边…"表示并列关系。', true),
      mkJudge('"不是…而是…"表示并列关系。', true),
      mkChoice('下列哪个是条件复句？', '只要功夫深，铁杵磨成针。', ['他不仅学习好，而且爱劳动。', '虽然天黑了，但他还在干活。', '因为生病，所以他没来。']),
      mkChoice('修改病句："昨天下了一整天雨，断断续续下个不停。"错误类型是？', '前后矛盾', ['成分残缺', '用词不当', '语序不当']),
      mkChoice('修改病句："老师耐心地教育我，对我的希望很大。"最好的改法是？', '老师耐心地教育我，对我寄予很大的希望。', ['老师教育我，希望很大。', '老师耐心希望我教育。', '对我希望很大，老师耐心教育。']),
      mkChoice('下列哪个是递进复句？', '他不但完成了作业，还帮妈妈做了家务。', ['他写作业，我看电视。', '他写完作业就去打球。', '要么他来，要么你去。']),
      mkChoice('修改病句："小组会上，大家互相做了自我批评。"应改为？', '小组会上，大家分别做了自我批评。', ['小组会上，大家互相批评别人。', '小组会上，自我批评了大家。', '大家做了互相的自我批评小组会。']),
      mkChoice('修改病句："我们讨论了并且听了王老师的报告。"错误类型是？', '语序不当（应先听后讨论）', ['用词不当', '成分残缺', '重复啰嗦']),
      mkChoice('修改病句："菜市场里有黄瓜、番茄、苹果等许多蔬菜。"错误类型是？', '归类不当', ['成分残缺', '前后矛盾', '重复啰嗦']),
      // v112 M6+L1
      mkJudge('"不但…而且…"表示并列关系。', false, '“不但…而且…”表示递进关系，后一分句比前一分句更进一步；并列关系常用“一边…一边…”表示。'),
      mkJudge('"宁可…也不…"表示转折关系。', false, '“宁可…也不…”表示选择关系，在权衡之后选择前者、舍弃后者，不属于转折关系。')
    ];
  }

  // ---- 修辞与表达 ----
  function cn6_rhetoric_pool() {
    return [
      mkChoice('"飞流直下三千尺，疑是银河落九天"用了什么修辞？', '夸张和比喻', ['只有夸张', '只有比喻', '只有拟人']),
      mkChoice('"漓江的水真静啊，静得让你感觉不到它在流动"用了？', '排比和夸张', ['只有排比', '只有比喻', '只有拟人']),
      mkChoice('下列句子用了排比的是？', '这里的山，高大巍峨；这里的水，清澈见底；这里的树，郁郁葱葱。', ['这里很高。', '这里山高水清树多。', '这里有山有水有树。']),
      mkChoice('"春风又绿江南岸"中"绿"字的妙处是？', '化静为动，写出春天的生机', ['颜色好看', '押韵', '字少']),
      mkJudge('"蜡烛流泪了"是比喻句。', false),
      mkChoice('"桃花潭水深千尺，不及汪伦送我情"用了什么修辞？', '夸张和比喻', ['只有排比', '只有拟人', '只有对偶']),
      mkFill('"细密的雨丝，像○的牛毛"（填比喻相关词）：____', '细细', ['细细', '细细的', '细密', '轻柔']),
      mkJudge('反问句就是无疑而问，明知故问，用疑问的形式表达肯定的意思。', true),
      mkChoice('下列哪个不是常见的修辞手法？', '倒装', ['比喻', '拟人', '排比']),
      mkChoice('"盼望着，盼望着，东风来了，春天的脚步近了"用了？', '反复和拟人', ['只有反复', '只有拟人', '只有比喻']),
      mkChoice('"太阳的脸红起来了"用了什么修辞？', '拟人', ['比喻', '排比', '设问']),
      mkChoice('设问和反问的主要区别是？', '设问自问自答，反问只问不答', ['设问语气更强烈', '反问需要回答', '两者没有区别']),
      mkChoice('"什么是路？就是从没路的地方践踏出来的。"用了？', '设问', ['反问', '比喻', '拟人']),
      mkChoice('"敌人的枪炮再厉害，也挡不住我们前进的步伐"用了？', '夸张', ['设问', '拟人', '对偶']),
      mkChoice('对偶的特点是？', '字数相等，结构相同，意思相关', ['句子越长越好', '问句回答自己', '连续使用三个相同句式']),
      mkChoice('"谁是我们最可爱的人呢？我们的战士。"这是？', '设问', ['反问', '疑问', '感叹']),
      mkChoice('夸张的作用是？', '突出事物特征，增强表达效果', ['让句子更长', '让人不相信', '节省字数']),
      mkChoice('引用诗句、名言的作用不包括？', '增加文章字数', ['增强说服力', '增添文采', '引起共鸣']),
      mkJudge('"教室里静得连一根针掉在地上都听得见"是夸张。', true),
      mkJudge('"他打了个哈欠，太阳就升起来了"不是夸张。', false),
      mkChoice('仿写比喻句"老师像园丁"，最恰当的是？', '书籍像阶梯，引领我们攀登高峰。', ['老师像很高的人。', '园丁像老师一样。', '老师像园丁一样工作。']),
      mkChoice('"捐出一份爱心，献出一片真情"这类句子用了？', '对偶', ['拟人', '夸张', '设问']),
      mkChoice('下列句子同时用了拟人和排比的是？', '小草在风中点头，小花在风中微笑，小树在风中招手。', ['风吹过草地。', '小草、小花和小树都很好看。', '风把小草吹弯了腰。']),
      mkChoice('"他种的瓜很甜，吃了还想吃"如果改为夸张，最恰当的是？', '他种的瓜甜得让人做梦都想吃。', ['他种的瓜比较甜。', '他种的瓜可能甜。', '他种的瓜甜不甜不知道。']),
      mkFill('仿写："如果你是一滴水，你是否滋润了一寸土地？"仿写：如果你是一线阳光，你是否____？', '照亮了一分黑暗'),
      mkChoice('排比句至少由几个结构相似的句子构成？', '三个', ['两个', '四个', '五个']),
      mkJudge('"月亮一露面，星星们都害羞地躲起来"运用了拟人。', true),
      mkChoice('"这件事难道不是他的错吗？"改为陈述句是？', '这件事是他的错。', ['这件事不是他的错。', '这件事可能是他的错。', '这件事谁也不知道。']),
      mkChoice('对比修辞的作用是？', '突出事物之间的差异', ['让句子更短', '增加字数', '押韵好听']),
      mkChoice('反复和排比的区别是？', '反复是相同词语句子的重复，排比是结构相似的不同句子', ['反复就是排比', '排比要重复相同的词', '两者完全相同']),
      // v112 M6+L1
      mkJudge('设问和反问一样，都是自问自答。', false, '设问是自问自答，用于引起注意；反问是只问不答，答案就在问句之中，语气更强烈。')
    ];
  }

