  function cn6_reading_pool() {
    const passages = [
      {
        text: '读书有多种方法。鲁迅先生说过，读书要"眼到、口到、心到、手到"。眼到，就是要仔细看；口到，就是要朗读出声；心到，就是要用心思考；手到，就是要做笔记。这"四到"缺一不可。只看不想，等于不读；只读不记，等于白读。好的读书习惯，能让我们受益终身。',
        qs: [
          mkChoice('这段话的主要观点是？', '读书要做到"四到"', ['鲁迅爱读书', '读书有很多种', '读书要朗读']),
          mkChoice('"心到"的意思是？', '用心思考', ['用心记', '心里想', '心情好']),
          mkChoice('作者认为"只看不想"会怎样？', '等于不读', ['等于白读', '等于没看', '等于不记']),
          mkJudge('这段话的结构是总分总。', true),
          mkChoice('文中引用鲁迅先生的话是为了？', '增强说服力，证明观点', ['说明鲁迅喜欢说话', '介绍鲁迅生平', '凑够字数']),
          mkChoice('"这四到缺一不可"说明？', '四个方面都很重要，要一起做到', ['只要做到一个就行', '手到最重要', '眼到最重要']),
          mkFill('读书"四到"指眼到、口到、心到、____。', '手到', ['手到', '口到', '心到', '眼到']),
          mkChoice('"只读不记，等于白读"强调的是什么的重要性？', '做笔记', ['朗读', '观察', '背诵']),
        ],
      },
      {
        text: '成功需要坚持。爱迪生发明电灯，试验了上千种材料，失败了无数次，最终才找到了合适的灯丝。如果他中途放弃，就不会有电灯的发明。做事也是如此，遇到困难不退缩，才能取得最后的成功。正所谓"宝剑锋从磨砺出，梅花香自苦寒来"。',
        qs: [
          mkChoice('这段话主要告诉我们的道理是？', '成功需要坚持', ['爱迪生发明电灯', '做事不能退缩', '宝剑和梅花']),
          mkChoice('文中举爱迪生的例子是为了？', '证明成功需要坚持', ['介绍电灯的发明过程', '说明失败是好事', '赞扬爱迪生']),
          mkChoice('"宝剑锋从磨砺出，梅花香自苦寒来"的意思是？', '成功需要经历磨炼', ['宝剑很锋利', '梅花很香', '冬天很冷']),
          mkJudge('这段话举爱迪生发明电灯的事例，来说明成功需要坚持。', true),
          mkChoice('读完这段话，给你的启示是？', '做事情要坚持不懈，不怕困难', ['发明东西很容易', '失败了就放弃', '只有发明家才需要坚持']),
          mkChoice('这段话先提出观点，再举事例，最后总结，这样写的好处是？', '层次清楚，让人更容易相信和记住', ['按时间顺序写', '按地点变化写', '只叙事不议论']),
          mkFill('本段的中心论点是成功需要____。', '坚持', ['坚持', '努力', '耐心', '恒心']),
        ],
      },
      {
        text: '时间对每个人都是公平的。有人把时间比作金钱，其实时间比金钱更宝贵。金钱用完了可以再挣，时间过去了就再也不会回来。鲁迅先生说过："时间就像海绵里的水，只要愿挤，总还是有的。"他一生把别人喝咖啡的时间都用在了工作上。我们小学生更应该珍惜时间，上课专心听讲，作业按时完成，让每一天都过得充实而有意义。',
        qs: [
          mkChoice('这段话要表达的中心观点是？', '要珍惜时间', ['金钱很重要', '鲁迅爱喝咖啡', '上课要专心']),
          mkChoice('"时间就像海绵里的水"用了什么修辞？', '比喻', ['拟人', '排比', '设问']),
          mkChoice('文中写鲁迅的事例是为了？', '证明伟人也珍惜时间', ['说明鲁迅不喝咖啡', '介绍鲁迅的爱好', '批评鲁迅工作太多']),
          mkJudge('"金钱用完了可以再挣，时间过去了就再也不会回来"运用了对比。', true),
          mkChoice('这段话结尾对我们的建议是？', '上课专心听讲，按时完成作业', ['多喝咖啡提神', '少工作多休息', '把时间存起来']),
          mkFill('本文把时间比作海绵里的水，说明时间可以____出来。', '挤', ['挤', '挤出来', '省', '腾']),
          mkChoice('这段话把时间和金钱放在一起比，是为了？', '突出时间比金钱更宝贵、一去不复返', ['说明金钱不重要', '说明时间可以挣钱', '没有目的']),
        ],
      },
      {
        text: '宽容是一种美德。清朝大学士张英的家人与邻居为一堵墙争执不休，写信向张英求助。张英回信道："千里修书只为墙，让他三尺又何妨。"家人看后主动退让三尺，邻居深受感动，也退让三尺，这便是有名的"六尺巷"。退一步海阔天空，宽容不仅能化解矛盾，还能赢得别人的尊重。',
        qs: [
          mkChoice('本段文字的中心论点是？', '宽容是一种美德', ['张英官职很大', '邻居都很友好', '墙的位置很重要']),
          mkChoice('文中"六尺巷"的故事是为了？', '举例证明宽容能化解矛盾', ['说明张家人怕邻居', '介绍安徽的景点', '说明墙很重要']),
          mkChoice('"让他三尺又何妨"体现了张英怎样的品质？', '宽容大度', ['胆小怕事', '不爱家人', '富有钱财']),
          mkJudge('"退一步海阔天空"的意思是退让反而会使局面更开阔。', true),
          mkChoice('这个故事给我们的启示是？', '与人相处要懂得宽容礼让', ['吃亏的事绝不做', '遇到争执要争到底', '写信比当面说好']),
          mkChoice('这段话先提出观点，再举例证明，这种结构是？', '总分结构', ['并列结构', '递进结构', '转折结构']),
          mkFill('宽容不仅能化解矛盾，还能赢得别人的____。', '尊重', ['尊重', '信任', '理解', '敬佩']),
          mkFill('"千里修书只为墙，让他____又何妨。"（填空）', '三尺'),
        ],
      },
    ];
    const items = [];
    passages.forEach(function (p) {
      p.qs.forEach(function (q) { items.push(Object.assign({}, q, { passage: p.text })); });
    });
    return items;
  }

