    qs.push(mkFill('《宿建德江》中"野旷天低树"的下一句是"____"。', '江清月近人'));
    qs.push(mkChoice('《六月二十七日望湖楼醉书》写的是什么景象？', '夏日骤雨来去匆匆', ['秋日霜降', '冬日飞雪', '春日微风']));
    qs.push(mkChoice('《宿建德江》的作者是？', '孟浩然', ['王维', '李白', '杜甫']));
