    qs.push(mkChoice('《灯光》的作者是？', '王愿坚', ['铁凝', '老舍', '宗璞']));
    qs.push(mkChoice('《灯光》中，郝副营长在战斗打响后点燃了什么？', '他珍藏的那本书', ['一堆干草', '一盏油灯', '一根火把']));
    qs.push(mkChoice('郝副营长点燃书本，是为了什么？', '为后续部队照亮前进的道路', ['为了烧掉敌人的工事', '为了取暖', '为了给战友发信号']));
