    qs.push(mkChoice('《盼》中的"我"盼望什么？', '下雨穿新雨衣', ['放假', '过生日', '出去玩']));
    qs.push(mkChoice('《盼》围绕"盼"写了哪些内容？', '盼变天、盼下雨、盼穿雨衣、终于穿上雨衣', ['盼考试得满分', '盼出去玩', '盼新玩具']));
