    qs.push(mkChoice('围绕中心选材，最重要的是？', '材料能表现中心', ['材料越多越好', '材料越怪越好', '材料越长越好']));
    qs.push(mkChoice('习作中"详略得当"的意思是？', '能突出中心的详写，其余略写', ['全部详写', '全部略写', '随机详略']));
    qs.push(mkChoice('《灯光》一课中，作者由什么引出了对郝副营长的回忆？', '天安门广场的灯光', ['一轮明月', '一阵大风', '一声鸟叫']));
    qs.push(mkChoice('《盼》中"我"的新雨衣是什么颜色的？', '淡绿色', ['红色', '蓝色', '黄色']));
    qs.push(cnAccJ('《盼》一课中，作者围绕"盼"字，写了许多与盼下雨有关的小事。', true));
    qs.push(cnRd('《灯光》中反复出现的"多好啊"在文中起什么作用？', '贯穿全文的线索', ['只是一句口头禅', '表示疑问', '表示惊讶'], '战斗间隙，郝副营长倚着交通沟的胸墙坐着，借着微弱的火光看一本破旧的书。书上有一幅插图，画的是一盏吊着的电灯，一个孩子正在灯下聚精会神地读书。他凝视着那幅图，轻轻地说："多好啊！"战斗打响后，为了让后续部队找到突破口，郝副营长点燃了那本珍藏的书，用火光为部队照亮了前进的路。那天夜晚，天安门广场千万盏灯静静地照着天安门广场周围的宏伟建筑，我又一次想起郝副营长说过的话——"多好啊！"'));
    qs.push(cnRd('片段中，"我"为什么盼着变天、盼着下雨？', '因为可以穿上新雨衣', ['因为讨厌太阳', '因为想出去玩', '因为要交作业'], '每天放学路上我都在想：太阳把天烤得这样干，还能长云彩吗？为什么我一有了雨衣，天气预报就总是"晴"呢？'));
    qs.push(cnRd('片段中"为什么我一有了雨衣，天气预报就总是晴呢"写出了"我"的什么心情？', '急切盼望下雨，好穿上新雨衣', ['无所谓', '害怕', '生气'], '每天放学路上我都在想：太阳把天烤得这样干，还能长云彩吗？为什么我一有了雨衣，天气预报就总是"晴"呢？'));
    qs.push(cnRd('这个片段主要写了什么？', '"我"盼着下雨好穿新雨衣的急切心情', ['天气总是晴', '放学路上的风景', '雨衣的样子'], '每天放学路上我都在想：太阳把天烤得这样干，还能长云彩吗？为什么我一有了雨衣，天气预报就总是"晴"呢？'));
    qs.push(cnRd('《盼》片段中，"我"为什么兴奋？', '因为盼了很久的雨终于要来了', ['因为要放学了', '因为捡到钱', '因为要过生日'], '有一天，快到家时，路边的小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑。我放慢了脚步，心想，雨点儿打在头上，才是世界上最美的事呢！果然，随着几声闷雷，头顶上真的落上了几个雨点儿。我又仰起头来，甩打着书包就大步跑进了楼门。'));
    qs.push(cnRd('片段中"小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑"用了什么修辞？', '拟人', ['比喻', '排比', '对偶'], '有一天，快到家时，路边的小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑。我放慢了脚步，心想，雨点儿打在头上，才是世界上最美的事呢！果然，随着几声闷雷，头顶上真的落上了几个雨点儿。我又仰起头来，甩打着书包就大步跑进了楼门。'));
    qs.push(cnRd('"雨点儿打在头上，才是世界上最美的事呢"表现了"我"？', '对雨的渴望，盼穿雨衣', ['讨厌下雨', '怕淋湿', '喜欢打伞'], '有一天，快到家时，路边的小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑。我放慢了脚步，心想，雨点儿打在头上，才是世界上最美的事呢！果然，随着几声闷雷，头顶上真的落上了几个雨点儿。我又仰起头来，甩打着书包就大步跑进了楼门。'));
    qs.push(cnRd('片段中"甩打着书包就大步跑进了楼门"写出"我"的？', '激动兴奋', ['垂头丧气', '慢吞吞', '不情愿'], '有一天，快到家时，路边的小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑。我放慢了脚步，心想，雨点儿打在头上，才是世界上最美的事呢！果然，随着几声闷雷，头顶上真的落上了几个雨点儿。我又仰起头来，甩打着书包就大步跑进了楼门。'));
    qs.push(cnAcc('语文园地·日积月累："五音"指的是？', '宫商角徵羽', ['哆来咪发唆', '青黄赤白黑', '东西南北中']));
