    qs.push(cnRd('《鲁滨逊漂流记》片段中，鲁滨逊把破船上的东西搬上岸，说明了什么？', '他机智冷静、善于利用条件', ['他喜欢收集东西', '他准备开商店', '他爱占小便宜'], '我就这样一边航行，一边收集东西。我在破船里找到了不少有用的东西：几盒饼干、几块面包、一些白兰地、几件衣服、还有两把刀和一把斧子。我把这些东西一一搬上岸，搭起一个帐篷。每天我都望着海面，盼着有船经过。'));
    qs.push(cnRd('"每天我都望着海面，盼着有船经过"表现了鲁滨逊？', '对获救的渴望和希望', ['绝望放弃', '觉得荒岛很好', '忘了回家'], '我就这样一边航行，一边收集东西。我在破船里找到了不少有用的东西：几盒饼干、几块面包、一些白兰地、几件衣服、还有两把刀和一把斧子。我把这些东西一一搬上岸，搭起一个帐篷。每天我都望着海面，盼着有船经过。'));
    qs.push(cnRd('"我把这些东西一一搬上岸，搭起一个帐篷"说明鲁滨逊？', '动手能力强，积极自救', ['很富有', '很懒惰', '只会等待救援'], '我就这样一边航行，一边收集东西。我在破船里找到了不少有用的东西：几盒饼干、几块面包、一些白兰地、几件衣服、还有两把刀和一把斧子。我把这些东西一一搬上岸，搭起一个帐篷。每天我都望着海面，盼着有船经过。'));
