    qs.push(mkChoice('本单元习作《让真情自然流露》要求？', '写一件真实的事，把真情实感表达出来', ['编一个虚构故事', '写一篇说明文', '只写天气']));
    qs.push(mkChoice('下列名言中，表达珍惜时间的是？', '少壮不努力，老大徒伤悲', ['学而不思则罔', '己所不欲勿施于人', '温故而知新']));
    qs.push(cnRd('《匆匆》片段中，作者用"燕子""杨柳""桃花"来衬托？', '时间的一去不复返', ['春天很美', '花朵鲜艳', '燕子可爱'], '燕子去了，有再来的时候；杨柳枯了，有再青的时候；桃花谢了，有再开的时候。但是，聪明的，你告诉我，我们的日子为什么一去不复返呢？——是有人偷了他们吧：那是谁？又藏在何处呢？是他们自己逃走了吧：现在又到了哪里呢？'));
    qs.push(cnRd('"我们的日子为什么一去不复返呢"是？', '设问（自问自答），引人思考', ['疑问句', '陈述句', '祈使句'], '燕子去了，有再来的时候；杨柳枯了，有再青的时候；桃花谢了，有再开的时候。但是，聪明的，你告诉我，我们的日子为什么一去不复返呢？——是有人偷了他们吧：那是谁？又藏在何处呢？是他们自己逃走了吧：现在又到了哪里呢？'));
    qs.push(cnRd('片段开头"燕子去了，有再来的时候"运用了什么修辞？', '排比', ['比喻', '夸张', '对偶'], '燕子去了，有再来的时候；杨柳枯了，有再青的时候；桃花谢了，有再开的时候。但是，聪明的，你告诉我，我们的日子为什么一去不复返呢？——是有人偷了他们吧：那是谁？又藏在何处呢？是他们自己逃走了吧：现在又到了哪里呢？'));
