    qs.push(cnRd('从这段描写看，父亲（李大钊）是一个怎样的人？', '慈祥、耐心、对子女亲切', ['惊慌失措', '低声下气', '愤怒咆哮'], '父亲是很慈祥的，从来没骂过我们，更没打过我们。我总爱向父亲问许多幼稚可笑的问题。他不论多忙，对我的问题总是很感兴趣，总是耐心地讲给我听。这一次不知道为什么，父亲竟这样含糊地回答我。后来听母亲说，军阀张作霖要派人来检查。为了避免党组织被破坏，父亲只好把一些书籍和文件烧掉。'));
