    qs.push(cnRd('《学弈》中，两个学生学棋的结果是？', '专心者学得好，三心二意者学得差', ['两人都学得好', '两人都学得差', '两人都放弃'], '弈秋，通国之善弈者也。使弈秋诲二人弈，其一人专心致志，惟弈秋之为听；一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之。虽与之俱学，弗若之矣。为是其智弗若与？曰：非然也。'));
