    qs.push(cnRd('《真理诞生于一百个问号之后》片段中，发现真理的人有什么共同特点？', '善于从细小的、司空见惯的现象中看出问题', ['运气特别好', '特别有钱', '很出名'], '纵观千百年来的科学技术发展史，那些定理、定律、学说的发现者、创立者，差不多都很善于从细小的、司空见惯的现象中看出问题，不断发问，不断解决疑问，追根求源，最后把"？"拉直变成"！"，找到了真理。'));
