    qs.push(cnMix('《盼》中"窸窸窣窣"的读音是？', 'xī xī sū sū', ['xī xī cuì cuì', 'sū sū xī xī', 'xí xí shuài shuài'], '六上·第五单元《盼》', '拟声词，形容细小的摩擦声，读 xī xī sū sū。'));
