    qs.push(cnMix('《宿建德江》"移舟泊烟渚"的下一句是？', '日暮客愁新', ['野旷天低树', '江清月近人', '明月别枝惊鹊'], '六上·第一单元《古诗词三首》', '《宿建德江》前两句：移舟泊烟渚，日暮客愁新。'));
